    "title": "核心短句 ①",
    "script": "我们先练三个最基础的招呼。第一句，“你好”。来，跟我读：“你好。”这句最稳妥，第一次见面、跟不太熟的人说都可以。第二句，“早啊”。早上见同事、朋友，比每次都说“早上好”更随意、更像日常口语。来：“早啊。”第三句，“你来了”。这个主要是看到熟人刚到的时候说，比如你已经在办公室了，同事刚进来，你很自然地说一句：“你来了。”注意，这不是在告诉他一个事实，很多时候它本身就是招呼。再连起来读一遍：“你好。早啊。你来了。”",
