    "title": "扩展短句：打招呼",
    "script": "除了“你好”，生活里还能听到很多招呼。比如很轻松的“嗨”，早上熟人之间常说“早”，完整一点可以说“晚上好”。看到认识的人也来了，可以说“你也来了”；看到对方刚到，可以问“刚到吗？”；早上发现对方来得特别早，可以说“这么早啊？”这里不用一次全背下来，先做到看见能认、听见能懂。还有一个小提醒：“晚上好”没问题，不过熟人日常聊天里通常不会每次都这么正式，具体怎么说还是要看关系和场景。",
