    "script": "这一页我们只练一个东西：“你呢？”为什么它这么重要？我问你：“最近怎么样？”你说：“还行。”可以，但话到这里很容易停。你再加一句：“你呢？”就等于把同一个问题问回来了，而且不用把“你最近怎么样”重新说一遍。中文里这样非常省力，也很自然。来，跟我读三组：“还行，你呢？”“挺好的，你呢？”“有点忙，你呢？”以后别人问你近况，回答完先想一件事：我能不能顺手加一句“你呢？”",
