    "title": "模板替换：你最近……吗？",
    "script": "再看另外一个模板：“你最近……吗？”比如：“你最近忙吗？”“你最近上班吗？”“你最近还好吗？”有“吗”的这种问句，通常是在问“是不是这样”，所以对方可以很简单地回答：“嗯，还行”“有点忙”“挺好的”。这里补充一个真实用法：“你最近上班吗？”是有具体语境的，比如你知道对方前段时间没上班，想问他最近有没有开始上班；平时普通寒暄，还是“最近忙吗？”更自然。回答以后一样别忘了：“你呢？”",
