    "page": 12,
    "title": "核心模板 ②：“了？”和“啊？”",
    "script": "熟人之间还有一类特别像中国人日常聊天的说法：“刚到啊？”“下班了？”“这么早啊？”你可能会觉得奇怪：人都站在我面前了，他明明看见我刚到，为什么还问？因为这种话很多时候不是为了得到信息，而是在打招呼、找个话头。比如同事准备走了，你说一句“下班了？”其实就跟“哎，走啦？”差不多。这里的“啊”“了”都让口气更像随口聊天。先别分析太深，先把这种感觉听熟。",
