    "title": "语法 ①：“吗”用于一般的是非问句",
    "script": "这一页讲一个最基础的“吗”。比如“你最近忙。”这是陈述。后面加一个“吗”，就变成“你最近忙吗？”再比如“今天上班。”加“吗”以后就是“今天上班吗？”所以初学阶段可以先简单记：一句陈述，后面加“吗”，常常就能变成一个“是不是这样”的问题。来，跟我读：“你最近忙吗？”“今天上班吗？”注意“吗”读轻声，不要读得特别重。",
