    "page": 14,
    "title": "语法 ②：“怎么样”后面不要再加“吗”",
    "script": "这里是一个很常见的错误。不要说：“最近怎么样吗？”为什么？因为“怎么样”本身已经是在问问题了，后面不用再加“吗”。正确就是：“最近怎么样？”同样，“工作怎么样？”“学习怎么样？”都不加“吗”。你可以把两种结构放在一起记：“最近忙吗？”——有“吗”；“最近怎么样？”——没有“吗”。我说一句错误的，你来改：“工作怎么样吗？”对，应该是“工作怎么样？”",
