    "page": 15,
    "title": "语法 ③：“呢”把问题自然问回去",
    "script": "现在看“呢”。这个字特别好用。A问：“最近怎么样？”B可以说：“还行，你呢？”这里的“你呢？”其实就是“那你怎么样？”但中文里前面的内容已经很清楚了，所以不用再重复一遍。A接着说：“我也还行。”这就是一轮很自然的小对话。初学阶段你甚至可以把“你呢？”当成一个完整的小块来记。别人问你什么，你回答完，很多时候都可以顺手来一句：“你呢？”",
