    "title": "多种说法：很久没见 / 问近况",
    "script": "一段时间没见，可以说“好久不见”，也可以说“好久没见了”。两句都能用，不过“好久不见”是最固定、最好记的一句。然后很自然就可以接近况：“最近怎么样？”“最近还好吗？”“最近忙吗？”比如见到老朋友：“好久不见！最近怎么样？”这两句连起来特别顺。大家跟我说一遍：“好久不见，最近怎么样？”很好。",
