    "title": "什么时候说哪一句？①",
    "script": "现在我们按场景来选一句。第一次见面，或者对方跟你不太熟，用“你好”最稳。早上见同事、熟人，可以直接“早啊”。如果你已经在一个地方，看到熟人刚刚过来，可以说“你来了”，也可以问“刚到啊？”所以大家不要形成一个习惯：不管见谁都只说“你好”。中文口语里，关系和场景不同，招呼方式也会跟着变。",
