    "script": "下面这些话，你现在不一定都要主动说，但别人对你说的时候一定要听懂。比如“吃了吗？”“去哪儿啊？”“忙着呢？”“最近还行吧？”这些都是熟人之间很常见的随口寒暄。尤其“吃了吗？”和“去哪儿啊？”，初学者很容易把它们听得太认真。先把声音和意思记住，下一页我们讲：为什么有些话看起来像问题，其实没那么认真地在问。",
