    "title": "必须听懂 ②：看起来“已经知道答案”",
    "script": "看这一组：“刚来啊？”“刚到啊？”“下班了？”“你也在啊？”“这么早啊？”你会发现，很多时候对方其实已经看到答案了。比如你背着包准备走，他还问你“下班了？”这不是他看不出来，而是熟人之间很自然的一句招呼。中国人日常聊天里，这种“明明大概知道答案还顺口问一句”的情况很多。听到以后不用紧张，简单回一句就行。",
