    "page": 23,
    "title": "必须听懂 ③：对方可能这样回答",
    "script": "别人问你近况，对方也可能用很短的方式回答。比如：“挺好的。”“还行吧。”“有点忙。”或者他回答完马上问你：“你呢？”这些都要做到一听就明白。“还行吧”里面有个“吧”，语气会更松一点，有点“还可以吧”的感觉。你不需要每次分析语法，先把这些整句听熟。以后别人说“还行吧”，你马上知道：他是在说最近还可以。",
