    "title": "别人问“去哪儿啊？”不用回答很详细",
    "script": "别人路上随口问你：“去哪儿啊？”不用回答得很详细。你可以说：“去上班。”“出去一下。”“去买点东西。”说到这里就够了。比如邻居碰到你：“去哪儿啊？”你说：“出去一下。”很自然，然后两个人各走各的。你不用说“我先去超市，再去银行，然后几点回来”。寒暄回答通常短一点反而更像真实口语。",
