    "title": "常见错误 ①：见到所有人都只说“你好”",
    "script": "来看第一个常见问题：见到所有人都只说“你好”。“你好”本身没有错，但如果是天天见的同事、熟人，每次都很正式地“你好”，会有一点像课本。早上可以说“早啊”，看到对方来了可以说“来了？”几天没见可以问“最近怎么样？”所以我们学口语，不只是学“对不对”，还要学“这个场景里中国人通常怎么说”。合适，比句子复杂更重要。",
