    "title": "常见错误 ③：“怎么样”后面加“吗”",
    "script": "第三个错误再巩固一次：“怎么样”后面不要加“吗”。错误是“最近怎么样吗？”正确是“最近怎么样？”但“最近忙吗？”是对的。你可以这样区分：“忙吗”是“是不是忙”；“怎么样”本身就是“情况如何”。所以我们读两句：“最近忙吗？”“最近怎么样？”再来一遍。以后看到“怎么样”，先提醒自己：后面一般不要再加“吗”。",
