    "script": "场景四，很久没见的朋友。A先说：“好久不见。”B可以回：“是啊，好久不见。”接下来别停，A问：“最近怎么样？”B说：“挺好的，你呢？”大家看，整个流程特别自然：先“好久不见”，再问“最近怎么样”，最后“回答 + 你呢”。不需要长篇大论，就这三步已经很像真实见面聊天了。来，我们把整段顺一遍，语速自然一点，不要像背课文。",
