    "script": "好，最后我们把今天最重要的六句收回来。第一：“你好。”第二：“早啊。”第三：“你来了。”第四：“好久不见。”第五：“最近怎么样？”第六：“还行，你呢？”今天虽然看了很多扩展说法，但不用一次全部背。先把这六句说自然、用得出来最重要。来，最后一起读一遍：“你好。早啊。你来了。好久不见。最近怎么样？还行，你呢？”很好。",
